<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">declare_furniture</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(server; home </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)       </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># inspector off again</span></span>
